    // We model a single call to c.play with an arbitrary amount and then assert
    // a general invariant relating address(c).balance and c.pot() after the call.
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward the requested amount
        require(address(this).balance >= amount);

        // record values before the call
        uint beforePot = c.pot();
        uint beforeBalanceC = address(c).balance;

        bool reverted;
        // call play with the provided amount; it should only accept exactly TICKET_AMOUNT
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPot = c.pot();
        uint afterBalanceC = address(c).balance;
        address bank = c.bank();

        // General rule to hold for all inputs:
        // - If the call reverted then state must be unchanged: pot and contract balance unchanged.
        // - If it did not revert then the contract balance change equals the change in pot plus at most FEE_AMOUNT transferred out to bank.
        //   That is: afterBalanceC + feePaid == beforeBalanceC + (afterPot - beforePot), where feePaid is either 0 or FEE_AMOUNT.
        // We express feePaid as a value that must be either 0 or 1 (FEE_AMOUNT = 1 in C).

        // compute observed delta values without underflow
        uint deltaPot = afterPot >= beforePot ? afterPot - beforePot : 0;
        uint deltaBalanceC = afterBalanceC >= beforeBalanceC ? afterBalanceC - beforeBalanceC : 0;

        // Check the assertions in one general assert
        assert(
            (reverted && afterPot == beforePot && afterBalanceC == beforeBalanceC)
            || (
                !reverted
                && (
                    // either pot was reset to 0 after a winning branch
                    (afterPot == 0 && (beforePot + (amount == C(address(c)).TICKET_AMOUNT() ? C(address(c)).TICKET_AMOUNT() : 0) == beforePot + (amount == C(address(c)).TICKET_AMOUNT() ? C(address(c)).TICKET_AMOUNT() : 0)))
                    // OR pot increased exactly by the ticket amount when no win occurred
                    || (afterPot == beforePot + (amount == C(address(c)).TICKET_AMOUNT() ? C(address(c)).TICKET_AMOUNT() : 0))
                )
                // and the contract balance change equals pot change minus possible fee 0 or 1
                && (
                    // either no fee was paid
                    (afterBalanceC == beforeBalanceC + deltaPot)
                    ||
                    // or fee 1 was paid out so contract balance increased by deltaPot - 1 (equivalently afterBalanceC + 1 == beforeBalanceC + deltaPot)
                    (afterBalanceC + 1 == beforeBalanceC + deltaPot)
                )
            )
        );
    }

    // accept Ether so c can transfer to this contract in rare cases (not used here)
    receive() external payable {}
