        uint potBefore = c.pot();
        uint balBefore = address(c).balance;

        bool reverted;
        // perform the call, capturing whether it reverted
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable state after the call
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;

        // compute deltas safely (avoid underflow in expressions inside assert)
        uint potIncreased = (potAfter > potBefore) ? (potAfter - potBefore) : 0;
        uint balDeltaPlus = (balAfter >= balBefore) ? (balAfter - balBefore) : 0;
        uint balDeltaMinus = (balBefore >= balAfter) ? (balBefore - balAfter) : 0;

        // General rule asserted:
        // - If the call reverted, pot and contract balance are unchanged.
        // - Otherwise (call succeeded): either pot increased by exactly 10 (ticket) or pot was reset to 0;
        //   and the change in contract balance equals the change in pot minus either 0 or 1 (fee <= 1).
        assert(
            (reverted && potAfter == potBefore && balAfter == balBefore)
            || (
                !reverted
                && (
                    // pot either increased by exactly 10 or became 0
                    potIncreased == 10 || potAfter == 0
                )
                && (
                    // balance change equals pot change (no fee) OR equals pot change minus 1 (fee of 1 paid out)
