            // Case B: pot reset to 0 and contract balance decreased by exactly (pot_before - fee), where fee = balance_before + amount - balance_after - (pot_before - 0)
            // Rearranged: the payout to caller equals pot_before - fee, so balance_after = balance_before + amount - (pot_before - fee) - fee_receiver? Instead compute payout = (balance_before + amount) - balance_after - fee_taken_by_bank
            // Simpler observable: when pot_after == 0, the net change in contract balance should be balance_after == balance_before + amount - (pot_before - /*unknown fee*/ ) - /*fee*/
            // But we can assert that if pot_after==0 then balance_after <= balance_before + amount and balance_after + (pot_before) <= balance_before + amount + 1 ether**0
            // To remain precise without constants, check that when pot becomes 0 the contract balance decreased by at most pot_before (it cannot lose more than pot_before plus maybe fee from the incoming amount).

            bool caseB = false;
            if (pot_after == 0) {
                // The contract's balance after should be <= balance_before + amount (it cannot gain more than incoming),
                // and should be >= balance_before + amount - pot_before - 1 ether + 1 /*we don't have constants so allow at most pot_before+amount decrease*/;
                // Simpler and sound observable rule: when pot becomes 0, the contract balance decreased by at most pot_before (i.e., balance_before + amount - balance_after <= pot_before + amount)
                // That simplifies to balance_after >= balance_before - pot_before.
                caseB = (pot_after == 0) && (balance_after >= balance_before - pot_before) && (balance_after <= balance_before + amount);
            }

            assert(bank_unchanged && (caseA || caseB));
        }
    }

    receive() external payable {}
